#nullable enable // autogenerated    
  
using MVZ2.GameContent.Contraptions;
using MVZ2.GameContent.Effects;
using MVZ2.GameContent.Enemies;
using MVZ2.GameContent.Pickups;
using MVZ2.GameContent.Seeds;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Localization;
using MVZ2.Vanilla.Pickups;
using MVZ2.Vanilla.Projectiles;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Blueprints;
using MVZ2Logic.Level;
using MVZ2Logic.Localization;
using PVZEngine;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Level;
using Tools;
using UnityEngine;
  
namespace MVZ2.GameContent.Stages  
{  
    [AutoStageDefinition(VanillaStageNames.HeavyWeapon_Plus)]  
    public class HeavyWeapon_Plus : HeavyWeaponStageBase  
    {  
        public HeavyWeapon_Plus(string nsp, string name) : base(nsp, name)  
        {  
        }  
  
        protected override NamespaceID[] GetBlueprintsID()  
        {  
            return new NamespaceID[]  
            {  
                VanillaBlueprintID.heavyWeaponFlashbang,  
                VanillaBlueprintID.HeavyWeaponGrenade,  
                VanillaBlueprintID.HeavyWeaponMolotov,  
                VanillaBlueprintID.HeavyWeaponInvincible,  
                VanillaBlueprintID.HeavyWeaponSwitchProjectile,  
                VanillaBlueprintID.HeavyWeaponRegen,  
                VanillaBlueprintID.heavyWeaponSpread,  
                VanillaBlueprintID.HeavyWeaponBulletUpgrade,  
                VanillaBlueprintID.HeavyWeaponExtraLife,  
                VanillaBlueprintID.HeavyWeaponSelfDestruct,  
            };
        }  
  
        // 仅本关（heavyWeapon）机制：第二面旗帜后，在矿车所在竖列从天而降敌方 TNT。    
        // 写在关卡定义里而非 HeavyWeaponStageBehaviour（那是所有重装兵器关卡共用的）。    
        public override void OnUpdate(LevelEngine level)  
        {  
            base.OnUpdate(level);
  
            if (!level.IsGameRunning())  
                return;
  
            // —— 每一大波（旗帜）到来时，从天而降一张红石矿卡片作为奖励 ——    
            // 用 level 属性记录上一次看到的旗帜数，检测到旗帜数增加（沿边触发）才掉一次卡，    
            // 避免同一面旗帜期间每帧重复掉落。    
            int currentFlag = level.CurrentFlag;
            if (currentFlag > GetLastRewardFlag(level))  
            {  
                SetLastRewardFlag(level, currentFlag);
                DropRedstoneOreCard(level);
            }  
  
            // 第二面旗帜之后才开始空袭
            if (level.CurrentFlag < START_FLAG)  
                return;
  
            // 空袭首次开始时弹出一次提示（用 level 属性记录，避免每帧重复）    
            if (!GetAirRaidAdviced(level))  
            {  
                SetAirRaidAdviced(level, true);
                level.ShowAdvice(LogicStrings.CONTEXT_ADVICE, VanillaStrings.ADVICE_HEAVY_WEAPON_AIR_RAID, 1000, 150);
            }  
  
            // 落弹计时器（懒初始化，存在关卡属性里）    
            var timer = GetDropTimer(level);
            if (timer == null)  
            {  
                timer = new FrameTimer(DROP_INTERVAL);
                SetDropTimer(level, timer);
            }  
  
            timer.Run();
            if (timer.Expired)  
            {  
                timer.Reset();
                DropBombOnCartColumn(level);
            }  
        }  
  
        // 从天而降一张红石矿蓝图卡片（奖励）    
        private void DropRedstoneOreCard(LevelEngine level)  
        {  
            var rng = level.GetSpawnRNG();
  
            // 随机选一列、一行作为落点（横向随机，纵向取该行的 z）    
            int column = rng.Next(level.GetMaxColumnCount());
            int lane = rng.Next(level.GetMaxLaneCount());
            float x = level.GetEntityColumnX(column);
            float z = level.GetEntityLaneZ(lane);
            float groundY = level.GetGroundY(x, z);
  
            // 卡片内容 = 红石矿蓝图；卡片自带重力，从高空生成后自然下落    
            var param = new SpawnParams();
            var blueprintID = LogicBlueprintID.FromEntity(VanillaContraptionID.RedStoneOre);
            param.SetProperty(VanillaPickupProps.CONTENT_ID, blueprintID);
  
            var source = new Vector3(x, groundY + CARD_DROP_HEIGHT, z);
            level.Spawn(VanillaPickupID.blueprintPickup, source, null, param);
        }  
  
        // 在矿车所在竖列的随机一行从天而降一枚敌方 TNT    
        private void DropBombOnCartColumn(LevelEngine level)  
        {  
            // 场上唯一矿车（没有就不落弹）    
            var cart = MinecartRideable.FindSingleCart(level);
            if (cart == null)  
                return;
  
            // 矿车所在列    
            int column = level.GetColumn(cart.GetCenter().x);
            float x = level.GetEntityColumnX(column);
  
            // 该列随机一行为落点    
            var rng = level.GetSpawnRNG();
            int lane = rng.Next(level.GetMaxLaneCount());
            float z = level.GetEntityLaneZ(lane);
            float y = level.GetGroundY(x, z);
            var target = new Vector3(x, y, z);
  
            // 落点标识（加农炮指向标），到时自动消失    
            level.Spawn(VanillaEffectID.aimTarget, target, null)?.Let(m =>  
            {  
                m.Timeout = WARNING_FRAMES;
            });
  
            // 敌方 TNT：赋予阵营 + 伤害 + 抗坠落伤害    
            var param = new SpawnParams();
            param.SetProperty(EngineEntityProps.FACTION, level.Option.RightFaction);
            param.SetProperty(VanillaEntityProps.DAMAGE, BOMB_DAMAGE);
            param.SetProperty(VanillaEntityProps.FALL_RESISTANCE, 100000f);
  
            // 从高处抛落，用 lob 速度在 WARNING_FRAMES 内砸到落点    
            var source = new Vector3(x, y + DROP_HEIGHT, z);
            level.Spawn(VanillaEnemyID.MannequinTNT, source, null, param)?.Let(bomb =>  
            {  
                bomb.Velocity = VanillaProjectileExt.GetLobVelocityByTime(  
                    source, target, WARNING_FRAMES, bomb.GetGravity());
  
                // MannequinTNT 会自燃，默认 30 帧就炸；直接覆盖它自己的爆炸计时器，    
                // 让爆炸时机与落地(WARNING_FRAMES)大致同步，留 5 帧余量。    
                MannequinTNT.SetExplosionTimer(bomb, new FrameTimer(WARNING_FRAMES + 60));
            });
        }  
  
        // —— 关卡属性 & 常量 ——    
        public static FrameTimer? GetDropTimer(LevelEngine level) => level.GetProperty<FrameTimer>(PROP_DROP_TIMER);
        public static void SetDropTimer(LevelEngine level, FrameTimer timer) => level.SetProperty(PROP_DROP_TIMER, timer);
  
        public const int START_FLAG = 4;        // 第2面旗帜之后开始落弹    
        public const int DROP_INTERVAL = 180;    // 落弹间隔（帧）    
        public const int WARNING_FRAMES = 45;   // 预警时长/落体时间（帧）    
        public const float DROP_HEIGHT = 800f;  // TNT 起始高度    
        public const float BOMB_DAMAGE = 1800f; // TNT 伤害    
        public const float CARD_DROP_HEIGHT = 800f; // 红石矿卡片起始高度    
  
        private const string PROP_REGION = "heavy_weapon_stage_bombing";
        [LevelPropertyRegistry(PROP_REGION)]  
        public static readonly VanillaLevelPropertyMeta<FrameTimer> PROP_DROP_TIMER =  
            new VanillaLevelPropertyMeta<FrameTimer>("hw_drop_timer");
  
        public static bool GetAirRaidAdviced(LevelEngine level) => level.GetProperty<bool>(PROP_AIR_RAID_ADVICED);
        public static void SetAirRaidAdviced(LevelEngine level, bool value) => level.SetProperty(PROP_AIR_RAID_ADVICED, value);
  
        [LevelPropertyRegistry(PROP_REGION)]  
        public static readonly VanillaLevelPropertyMeta<bool> PROP_AIR_RAID_ADVICED =  
            new VanillaLevelPropertyMeta<bool>("hw_air_raid_adviced");
  
        // 记录上一次已发放奖励的旗帜数，用于沿边检测「新的一大波到来」    
        public static int GetLastRewardFlag(LevelEngine level) => level.GetProperty<int>(PROP_LAST_REWARD_FLAG);
        public static void SetLastRewardFlag(LevelEngine level, int value) => level.SetProperty(PROP_LAST_REWARD_FLAG, value);
  
        [LevelPropertyRegistry(PROP_REGION)]  
        public static readonly VanillaLevelPropertyMeta<int> PROP_LAST_REWARD_FLAG =  
            new VanillaLevelPropertyMeta<int>("hw_last_reward_flag");
    }  
}
